using MeiErp.Platform.Printing;
using MeiErp.Platform.Reporting;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using static MeiErp.Platform.Reporting.ReportRowBuilder;

namespace MeiErp.Modules.Repair;

public static class RepairReportRegistration
{
    public static IServiceCollection AddRepairReports(this IServiceCollection services)
    {
        services.AddScoped(sp=>Jobs(sp));services.AddScoped(sp=>Pipeline(sp));services.AddScoped(sp=>Ageing(sp));
        services.AddScoped(sp=>Turnaround(sp));
        services.AddScoped(sp=>Diagnoses(sp));
        services.AddScoped(sp=>Technicians(sp));services.AddScoped(sp=>Failures(sp));
        services.AddScoped(sp=>Symptoms(sp));services.AddScoped(sp=>WarrantyMix(sp));
        return services;
    }
    private static (DateOnly From,DateOnly To) Range(ReportRequest r,IServiceProvider sp){var today=sp.GetRequiredService<MeiErp.Platform.Kernel.IClock>().Today;return(r.From??today.AddMonths(-1),r.To??today);}
    private static ReportDefinition Jobs(IServiceProvider sp)=>new(){Key="repair.job-register",Name="Job register",Description="Devices received and their current workshop position.",ModuleKey=RepairModule.Key,Group="Registers",Permission=RepairModule.JobsView,Uses=ReportFilters.DateRange|ReportFilters.Status,SortOrder=1,Run=async(r,ct)=>{var (from,to)=Range(r,sp);var q=sp.GetRequiredService<RepairDbContext>().Jobs.AsNoTracking().Where(x=>x.ReceivedOn>=from&&x.ReceivedOn<=to);if(Enum.TryParse<JobStatus>(r.Status,true,out var status))q=q.Where(x=>x.Status==status);var rows=await q.OrderByDescending(x=>x.ReceivedOn).Take(3000).ToListAsync(ct);return new(){Columns=[new("date","Received",ReportValueKind.Date,1),new("number","Job",ReportValueKind.Text,1),new("customer","Customer",ReportValueKind.Text,2),new("device","Device",ReportValueKind.Text,2),new("serial","Serial",ReportValueKind.Text,1.2f),new("priority","Priority",ReportValueKind.Status,1),new("status","Status",ReportValueKind.Status,1)],Rows=[..rows.Select(x=>Row($"/repair/jobs/{x.Id}",("date",x.ReceivedOn),("number",x.Number),("customer",x.CustomerName),("device",$"{x.Make} {x.Model} {x.DeviceType}".Trim()),("serial",x.SerialNumber),("priority",x.Priority.ToString()),("status",x.Status.ToString())))],Header=[new PrintField("Period",$"{from:d MMM yyyy} – {to:d MMM yyyy}")]};}};
    private static ReportDefinition Pipeline(IServiceProvider sp)=>new(){Key="repair.pipeline",Name="Workshop pipeline",Description="Current workload by stage.",ModuleKey=RepairModule.Key,Group="Operations",Permission=RepairModule.JobsView,Uses=ReportFilters.None,SortOrder=2,Run=async(_,ct)=>{var rows=await sp.GetRequiredService<RepairDbContext>().Jobs.AsNoTracking().GroupBy(x=>x.Status).Select(x=>new{x.Key,Count=x.Count()}).OrderBy(x=>x.Key).ToListAsync(ct);var total=rows.Sum(x=>x.Count);return new(){Columns=[new("stage","Stage",ReportValueKind.Status,2),new("jobs","Jobs",ReportValueKind.Number,1),new("share","Share %",ReportValueKind.Number,1)],Rows=[..rows.Select(x=>Row(null,("stage",x.Key.ToString()),("jobs",x.Count),("share",total==0?0:Math.Round(x.Count*100m/total,1))))],Totals=[new("jobs",total)]};}};
    private static ReportDefinition Ageing(IServiceProvider sp)=>new(){Key="repair.open-ageing",Name="Open-job ageing",Description="Open devices that may be getting forgotten on a bench.",ModuleKey=RepairModule.Key,Group="Operations",Permission=RepairModule.JobsView,Uses=ReportFilters.None,SortOrder=3,Run=async(_,ct)=>{var open=JobWorkflow.Open;var rows=await sp.GetRequiredService<RepairDbContext>().Jobs.AsNoTracking().Where(x=>open.Contains(x.Status)).OrderBy(x=>x.CreatedUtc).ToListAsync(ct);return new(){Columns=[new("job","Job",ReportValueKind.Text,1),new("customer","Customer",ReportValueKind.Text,2),new("device","Device",ReportValueKind.Text,2),new("status","Stage",ReportValueKind.Status,1),new("days","Age days",ReportValueKind.Number,1),new("promised","Promised",ReportValueKind.Date,1)],Rows=[..rows.Select(x=>Row($"/repair/jobs/{x.Id}",("job",x.Number),("customer",x.CustomerName),("device",x.DeviceType),("status",x.Status.ToString()),("days",Math.Max(0,(sp.GetRequiredService<MeiErp.Platform.Kernel.IClock>().UtcNow-x.CreatedUtc).Days)),("promised",x.PromisedOn)))]};}};
    private static ReportDefinition Turnaround(IServiceProvider sp)=>new(){Key="repair.turnaround",Name="Turnaround",Description="Delivery speed and promised-date performance.",ModuleKey=RepairModule.Key,Group="Operations",Permission=RepairModule.CostsView,Uses=ReportFilters.DateRange,SortOrder=4,Run=async(r,ct)=>{var(from,to)=Range(r,sp);var rows=await sp.GetRequiredService<RepairDbContext>().Jobs.AsNoTracking().Where(x=>x.ReceivedOn>=from&&x.ReceivedOn<=to).OrderByDescending(x=>x.ReceivedOn).ToListAsync(ct);return new(){Columns=[new("job","Job",ReportValueKind.Text,1),new("customer","Customer",ReportValueKind.Text,2),new("received","Received",ReportValueKind.Date,1),new("delivered","Delivered",ReportValueKind.Date,1),new("days","Days",ReportValueKind.Number,1),new("late","Late",ReportValueKind.Status,1)],Rows=[..rows.Select(x=>Row($"/repair/jobs/{x.Id}",("job",x.Number),("customer",x.CustomerName),("received",x.ReceivedOn),("delivered",x.DeliveredUtc),("days",x.DeliveredUtc is null?null:Math.Round((x.DeliveredUtc.Value-x.CreatedUtc).TotalDays,1)),("late",x.PromisedOn is not null&&(x.DeliveredUtc is null?sp.GetRequiredService<MeiErp.Platform.Kernel.IClock>().Today:DateOnly.FromDateTime(x.DeliveredUtc.Value))>x.PromisedOn?"Yes":"No")))]};}};
    private static ReportDefinition Diagnoses(IServiceProvider sp)=>new(){Key="repair.diagnosis-activity",Name="Diagnosis activity",Description="Technical findings recorded by technician.",ModuleKey=RepairModule.Key,Group="Operations",Permission=RepairModule.Diagnose,Uses=ReportFilters.DateRange,SortOrder=9,Run=async(r,ct)=>{var(from,to)=Range(r,sp);var start=from.ToDateTime(TimeOnly.MinValue);var end=to.AddDays(1).ToDateTime(TimeOnly.MinValue);var rows=await sp.GetRequiredService<RepairDbContext>().RepairDiagnoses.AsNoTracking().Include(x=>x.Job).Where(x=>x.CreatedUtc>=start&&x.CreatedUtc<end).OrderByDescending(x=>x.CreatedUtc).ToListAsync(ct);return new(){Columns=[new("date","Date",ReportValueKind.Date,1),new("job","Job",ReportValueKind.Text,1),new("technician","Technician",ReportValueKind.Text,1.5f),new("findings","Findings",ReportValueKind.Text,4),new("days","Est. days",ReportValueKind.Number,1)],Rows=[..rows.Select(x=>Row($"/repair/jobs/{x.JobId}",("date",x.CreatedUtc),("job",x.Job!.Number),("technician",x.TechnicianName),("findings",x.Findings),("days",x.EstimatedDays)))]};}};
    private static ReportDefinition Technicians(IServiceProvider sp)=>new(){Key="repair.technician-performance",Name="Technician performance",Description="Assigned, delivered, open, diagnoses, turnaround and revenue by technician.",ModuleKey=RepairModule.Key,Group="Management",Permission=RepairModule.CostsView,Uses=ReportFilters.DateRange,SortOrder=11,Run=async(r,ct)=>{var(from,to)=Range(r,sp);var db=sp.GetRequiredService<RepairDbContext>();var jobs=await db.Jobs.AsNoTracking().Where(x=>x.ReceivedOn>=from&&x.ReceivedOn<=to&&x.AssignedToName!=null).ToListAsync(ct);var diag=await db.RepairDiagnoses.AsNoTracking().Where(x=>x.CreatedUtc>=from.ToDateTime(TimeOnly.MinValue)&&x.CreatedUtc<to.AddDays(1).ToDateTime(TimeOnly.MinValue)).GroupBy(x=>x.TechnicianName).Select(x=>new{x.Key,Count=x.Count()}).ToDictionaryAsync(x=>x.Key,x=>x.Count,ct);var rows=jobs.GroupBy(x=>x.AssignedToName!).Select(g=>new{Name=g.Key,Assigned=g.Count(),Delivered=g.Count(x=>x.DeliveredUtc!=null),Open=g.Count(x=>JobWorkflow.Open.Contains(x.Status)),Diagnoses=diag.GetValueOrDefault(g.Key),Days=g.Where(x=>x.DeliveredUtc!=null).Select(x=>(x.DeliveredUtc!.Value-x.CreatedUtc).TotalDays).DefaultIfEmpty().Average(),Revenue=g.Sum(x=>x.Total)}).OrderByDescending(x=>x.Delivered).ToList();return new(){Columns=[new("name","Technician",ReportValueKind.Text,2),new("assigned","Assigned",ReportValueKind.Number,1),new("delivered","Delivered",ReportValueKind.Number,1),new("open","Open",ReportValueKind.Number,1),new("diagnoses","Diagnoses",ReportValueKind.Number,1),new("days","Avg days",ReportValueKind.Number,1),new("revenue","Job value",ReportValueKind.Money,1.2f)],Rows=[..rows.Select(x=>Row(null,("name",x.Name),("assigned",x.Assigned),("delivered",x.Delivered),("open",x.Open),("diagnoses",x.Diagnoses),("days",Math.Round(x.Days,1)),("revenue",x.Revenue)))]};}};
    private static ReportDefinition Failures(IServiceProvider sp)=>new(){Key="repair.failure-analysis",Name="Brand and model failures",Description="Equipment frequency, repeat serials, turnaround, and job value.",ModuleKey=RepairModule.Key,Group="Analysis",Permission=RepairModule.CostsView,Uses=ReportFilters.DateRange,SortOrder=13,Run=async(r,ct)=>{var(from,to)=Range(r,sp);var jobs=await sp.GetRequiredService<RepairDbContext>().Jobs.AsNoTracking().Where(x=>x.ReceivedOn>=from&&x.ReceivedOn<=to).ToListAsync(ct);var rows=jobs.GroupBy(x=>new{Brand=x.Make??"(unspecified)",x.Model,x.DeviceType}).Select(g=>new{g.Key.Brand,g.Key.Model,g.Key.DeviceType,Jobs=g.Count(),Repeat=g.Where(x=>!string.IsNullOrWhiteSpace(x.SerialNumber)).GroupBy(x=>x.SerialNumber).Count(x=>x.Count()>1),Days=g.Where(x=>x.DeliveredUtc!=null).Select(x=>(x.DeliveredUtc!.Value-x.CreatedUtc).TotalDays).DefaultIfEmpty().Average(),Value=g.Sum(x=>x.Total)}).OrderByDescending(x=>x.Jobs).ToList();return new(){Columns=[new("brand","Brand",ReportValueKind.Text,1.5f),new("model","Model",ReportValueKind.Text,1.5f),new("device","Device",ReportValueKind.Text,1.5f),new("jobs","Jobs",ReportValueKind.Number,1),new("repeat","Repeat units",ReportValueKind.Number,1),new("days","Avg days",ReportValueKind.Number,1),new("value","Job value",ReportValueKind.Money,1.2f)],Rows=[..rows.Select(x=>Row(null,("brand",x.Brand),("model",x.Model),("device",x.DeviceType),("jobs",x.Jobs),("repeat",x.Repeat),("days",Math.Round(x.Days,1)),("value",x.Value)))]};}};
    private static ReportDefinition Symptoms(IServiceProvider sp)=>new(){Key="repair.symptom-frequency",Name="Symptom frequency",Description="Reported symptom frequency and share of tagged jobs.",ModuleKey=RepairModule.Key,Group="Analysis",Permission=RepairModule.JobsView,Uses=ReportFilters.DateRange,SortOrder=14,Run=async(r,ct)=>{var(from,to)=Range(r,sp);var raw=await sp.GetRequiredService<RepairDbContext>().Jobs.AsNoTracking().Where(x=>x.ReceivedOn>=from&&x.ReceivedOn<=to&&x.Symptoms!=null).Select(x=>x.Symptoms!).ToListAsync(ct);var rows=raw.SelectMany(x=>x.Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)).GroupBy(x=>x,StringComparer.OrdinalIgnoreCase).Select(x=>new{Name=x.Key,Count=x.Count()}).OrderByDescending(x=>x.Count).ToList();var total=rows.Sum(x=>x.Count);return new(){Columns=[new("symptom","Symptom",ReportValueKind.Text,3),new("count","Reported",ReportValueKind.Number,1),new("share","Share %",ReportValueKind.Number,1)],Rows=[..rows.Select(x=>Row(null,("symptom",x.Name),("count",x.Count),("share",total==0?0:Math.Round(x.Count*100m/total,1))))],Totals=[new("count",total)]};}};
    private static ReportDefinition WarrantyMix(IServiceProvider sp)=>new(){Key="repair.warranty-mix",Name="Warranty versus paid",Description="Billable and goodwill/warranty workshop effort.",ModuleKey=RepairModule.Key,Group="Analysis",Permission=RepairModule.CostsView,Uses=ReportFilters.DateRange,SortOrder=17,Run=async(r,ct)=>{var(from,to)=Range(r,sp);var lines=await sp.GetRequiredService<RepairDbContext>().WorkItems.AsNoTracking().Include(x=>x.Job).Where(x=>x.Job!.ReceivedOn>=from&&x.Job.ReceivedOn<=to).ToListAsync(ct);var rows=lines.GroupBy(x=>x.IsBillable?"Paid":"Warranty / goodwill").Select(x=>new{Kind=x.Key,Lines=x.Count(),Quantity=x.Sum(y=>y.Quantity),Value=x.Sum(y=>y.LineTotal)}).ToList();return new(){Columns=[new("kind","Work type",ReportValueKind.Text,2),new("lines","Lines",ReportValueKind.Number,1),new("quantity","Quantity",ReportValueKind.Number,1),new("value","Value",ReportValueKind.Money,1.5f)],Rows=[..rows.Select(x=>Row(null,("kind",x.Kind),("lines",x.Lines),("quantity",x.Quantity),("value",x.Value)))],Totals=[new("lines",rows.Sum(x=>x.Lines)),new("quantity",rows.Sum(x=>x.Quantity)),new("value",rows.Sum(x=>x.Value))]};}};
}
